// 使用原真实询问业务与实际结果绑定；窄门不代完整World/驱动许可运行。
#define HANMO_CONTACT_INQUIRY_RECEIPTS_TEST_LIBRARY
#include "contact_inquiry_receipts_test.cpp"
#undef HANMO_CONTACT_INQUIRY_RECEIPTS_TEST_LIBRARY
#include "resident/domains/player_plan/plan_binding.hpp"
#include "resident/domains/player_plan/plan_lifecycle.hpp"
int main(){try{
    InquiryFixture f;f.accept();f.leave();const auto before=f.state;auto action=f.begin_inquiry();auto start=bind(f,before,contact_inquiry_action_kind,{ActionStarted{action},{}},1);
    const auto original_action=*f.common.action(action);require(player_plan_contact_inquiry_continuation(f.common,f.state,original_action),"exact original action can be continued");auto wrong=original_action;wrong.actor_id="player";require(!player_plan_contact_inquiry_continuation(f.common,f.state,wrong),"another participant cannot acquire listener continuation");wrong=original_action;wrong.remaining_ticks=2;require(!player_plan_contact_inquiry_continuation(f.common,f.state,wrong),"fabricated remaining duration rejected");
    auto source=query_contact_inquiry_action(f.common,f.state,"stranger",action);require(source.ok&&source.value,"source present");const auto& c=source.value->contact;InteractionSession session;session.id=c.session_id;session.actor_id=c.actor_id;session.dialogue_id=c.dialogue_id;session.node_id=c.node_id;session.phase="say";session.context.place_id=c.place_id;session.context.provider_actor_id=c.provider_actor_id;session.context.role_id=c.role_id;
    require(player_plan_contact_inquiry_meeting_matches(*source.value,session),"only the original say is exempt from manual stop");auto changed=session;changed.node_id="another";require(!player_plan_contact_inquiry_meeting_matches(*source.value,changed),"another question stops plan");changed=session;changed.context.kind="encounter";require(!player_plan_contact_inquiry_meeting_matches(*source.value,changed),"encounter is not original private say");changed=session;changed.pending_action_id="another";require(!player_plan_contact_inquiry_meeting_matches(*source.value,changed),"another waiting action not consumed");
    PlayerPlanState plan;plan.current=PlayerPlan{"plan","stranger",f.common.tick(),{},"",{}};PlayerPlanStep step;step.id="step";step.data=PlayerPlanContinue{action};step.source={PlayerPlanSourceKind::existing_action,action,f.common.tick()};plan.current->steps.push_back(step);
    const auto active=f.state;auto completed=f.finish_inquiry(action);AdvanceDetails advance;ActionCompletion completion;completion.ok=true;completion.completed=true;completion.success=true;completion.code="ContactInquiryAnswered";advance.completed_actions.insert(action,completion);auto result=bind(f,active,"advance",{advance,{}},2);auto done=query_contact_inquiry_completion(f.common,f.state,"stranger",action,*result->details,result->tick,result->result_id);require(done.ok&&done.value&&done.value->success,"actual completion binding");require(!player_plan_contact_inquiry_continuation(f.common,f.state,original_action),"finished action cannot be reopened");require(!player_plan_contact_inquiry_meeting_matches(*done.value,session),"finished inquiry does not authorize continued dialogue");
    require(player_plan_record_started(plan,"plan","step",action,result->result_id,result->tick).ok,"Continue starts on its first real Advance, not the earlier ActionStarted receipt");require(player_plan_record_completed(plan,"plan","step",action,result->result_id,result->tick,true,"ContactInquiryAnswered").ok,"original successful inquiry ends its plan step");require(plan.current->steps.front().phase==PlayerPlanStepPhase::completed,"known/unknown/refusal meeting success remains original code");require(!player_plan_record_completed(plan,"plan","step",action,start->result_id,result->tick,true,"ContactInquiryAnswered").ok,"old result cannot replace actual completion");
    auto mixed=advance;mixed.completed_actions.find(action)->military_field_order={"forged"};require(!query_contact_inquiry_completion(f.common,f.state,"stranger",action,{mixed,{}},result->tick,result->result_id).ok,"mixed military result rejected");mixed=advance;mixed.completed_actions.find(action)->code.reset();require(!query_contact_inquiry_completion(f.common,f.state,"stranger",action,{mixed,{}},result->tick,result->result_id).ok,"missing code cannot become ordinary arrival");
    InquiryFixture interrupted;const auto initial=interrupted.state;auto failed_action=interrupted.begin_inquiry();auto failed_start=bind(interrupted,initial,contact_inquiry_action_kind,{ActionStarted{failed_action},{}},1);const auto pending=interrupted.state;interrupted.shared->places.insert("elsewhere",{"elsewhere","town",{}});interrupted.common.state().actors.find("sender")->location=SettlementLocation{"town","elsewhere"};auto failure=interrupted.finish_inquiry(failed_action);AdvanceDetails failed_advance;ActionCompletion failed;failed.ok=true;failed.completed=true;failed.success=false;failed.code=failure.reason;failed_advance.completed_actions.insert(failed_action,failed);auto failed_result=bind(interrupted,pending,"advance",{failed_advance,{}},2);auto failed_source=query_contact_inquiry_completion(interrupted.common,interrupted.state,"stranger",failed_action,*failed_result->details,failed_result->tick,failed_result->result_id);require(failed_source.ok&&failed_source.value&&!failed_source.value->success&&failed_source.value->reason=="ContactInquiryMeetingChanged","original failure cannot become travel success");
    PlayerPlanState stopped;stopped.current=PlayerPlan{"failed_plan","stranger",failed_start->tick,{},"",{}};step.id="failed_step";step.data=PlayerPlanContinue{failed_action};step.source={PlayerPlanSourceKind::existing_action,failed_action,failed_start->tick};stopped.current->steps.push_back(step);require(player_plan_record_started(stopped,"failed_plan","failed_step",failed_action,failed_result->result_id,failed_result->tick).ok,"failed plan binds first real Advance");require(player_plan_record_completed(stopped,"failed_plan","failed_step",failed_action,failed_result->result_id,failed_result->tick,false,failed_source.value->reason).ok&&stopped.current->steps.front().phase==PlayerPlanStepPhase::blocked,"failed inquiry keeps the real blocked result");
    std::cout<<"PLAYER_PLAN_CONTACT_INQUIRY: exact source, say context and actual completion; full World unrun\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
